// Calculate timestamps for the past 7 days (ISO 8601)
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

return [{
  json: {
    since: sevenDaysAgo.toISOString(),
    until: now.toISOString(),
    repo_owner: $env.GITHUB_REPO_OWNER || 'owner',
    repo_name: $env.GITHUB_REPO_NAME || 'repo',
    target_branch: $env.GITHUB_BRANCH || 'main'
  }
}];

const windowData = $('Calculate Date Window (7 Days)').first().json;
const sinceDate = new Date(windowData.since);

// Aggregate Commits
const rawCommits = $('Fetch Recent Commits').all().map(item => item.json);
const commits = rawCommits.map(c => ({
  sha: (c.sha || '').substring(0, 7),
  author: c.commit?.author?.name || c.author?.login || 'Unknown',
  message: (c.commit?.message || '').split('\n')[0],
  date: c.commit?.author?.date || c.commit?.committer?.date
})).filter(c => c.message.length > 0);

// Aggregate Merged PRs (filter only those merged within the 7-day window)
const rawPRs = $('Fetch Merged PRs').all().map(item => item.json);
const mergedPRs = rawPRs.filter(pr => {
  if (!pr.merged_at) return false;
  const mergedAt = new Date(pr.merged_at);
  return mergedAt >= sinceDate;
}).map(pr => ({
  number: pr.number,
  title: pr.title,
  author: pr.user?.login || 'Unknown',
  merged_at: pr.merged_at,
  html_url: pr.html_url,
  body: (pr.body || '').substring(0, 300)
}));

const metadataPayload = {
  repository: `${windowData.repo_owner}/${windowData.repo_name}`,
  timeframe: `${windowData.since.split('T')[0]} to ${windowData.until.split('T')[0]}`,
  total_commits: commits.length,
  total_merged_prs: mergedPRs.length,
  commits: commits,
  merged_prs: mergedPRs
};

const prompt = `You are an executive technical lead and engineering scribe preparing a high-level weekly development summary for stakeholders and engineering team members.

Repository: ${metadataPayload.repository}
Period: ${metadataPayload.timeframe}
Total Commits: ${metadataPayload.total_commits}
Total Merged Pull Requests: ${metadataPayload.total_merged_prs}

### Merged Pull Requests:
${mergedPRs.length > 0 ? mergedPRs.map(p => `- [#${p.number}] ${p.title} (@${p.author}) - ${p.html_url}`).join('\n') : 'None in this period.'}

### Commit History:
${commits.length > 0 ? commits.map(c => `- [${c.sha}] ${c.message} (@${c.author})`).join('\n') : 'No commits in this period.'}

Instructions:
Generate a structured, polished Markdown weekly development summary with the following sections:
1. 🚀 **Executive Summary**: 2-3 sentence overview highlighting key accomplishments and engineering velocity.
2. 🌟 **Key Features & Enhancements**: Grouped highlights of notable additions or architectural improvements.
3. 🐛 **Bug Fixes & Maintenance**: Significant stability, refactoring, or bug fix items.
4. 📊 **Metrics & Activity**: High-level velocity stats (# of PRs merged, commit count, top contributors).
5. 🔮 **Upcoming Focus / Notes**: Any strategic observations based on merged work.

Format cleanly in GitHub-flavored Markdown. Do not include markdown code fence wrappers around the whole document.`;

return [{
  json: {
    metadata: metadataPayload,
    prompt: prompt
  }
}];

const claudeResponse = $json;
const summaryText = claudeResponse.content?.[0]?.text || 'No summary generated.';
const metadata = $('Format Git Metadata & Prompt').first().json.metadata;

// Format payload suitable for Slack/Discord/generic incoming webhook
return [{
  json: {
    summary_markdown: summaryText,
    repository: metadata.repository,
    timeframe: metadata.timeframe,
    slack_payload: {
      text: `*Weekly Dev Summary: ${metadata.repository} (${metadata.timeframe})*\n\n${summaryText}`,
      mrkdwn: true
    },
    discord_payload: {
      content: `**Weekly Dev Summary: ${metadata.repository} (${metadata.timeframe})**\n\n${summaryText.substring(0, 1900)}`
    }
  }
}];
